From 5fb97b954c02d1624cf12dc24f678d624e668785 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:01:15 +0100
Subject: [PATCH] libtaskmanager: match renamed .desktop launchers to their
 windows

A launcher pinned from a renamed copy of a .desktop file, e.g. on the
desktop, used the file name as its app id, so its windows never matched
it. Use the installed application with the same Exec line instead.

BUG: 403983
---
 libtaskmanager/launchertasksmodel.cpp | 35 ++++++++++++++++++++++++++-
 1 file changed, 34 insertions(+), 1 deletion(-)

diff --git a/libtaskmanager/launchertasksmodel.cpp b/libtaskmanager/launchertasksmodel.cpp
index e86375e27a..f2d4e93e52 100644
--- a/libtaskmanager/launchertasksmodel.cpp
+++ b/libtaskmanager/launchertasksmodel.cpp
@@ -7,6 +7,7 @@
 #include "launchertasksmodel.h"
 #include "tasktools.h"

+#include <KApplicationTrader>
 #include <KDesktopFile>
 #include <KNotificationJobUiDelegate>
 #include <KService>
@@ -60,10 +61,12 @@ public:
     }

     QHash<QUrl, AppData> appDataCache;
+    QHash<QUrl, QString> appIdCache;
     QTimer sycocaChangeTimer;

     void init();
     AppData appData(const QUrl &url);
+    QString appId(const QUrl &url);

     bool requestAddLauncherToActivities(const QUrl &_url, const QStringList &activities);
     bool requestRemoveLauncherFromActivities(const QUrl &_url, const QStringList &activities);
@@ -88,6 +91,7 @@ void LauncherTasksModel::Private::init()
         }

         appDataCache.clear();
+        appIdCache.clear();

         // Emit changes of all roles satisfied from app data cache.
         Q_EMIT q->dataChanged(q->index(0, 0),
@@ -121,6 +125,34 @@ AppData LauncherTasksModel::Private::appData(const QUrl &url)
     return data;
 }

+QString LauncherTasksModel::Private::appId(const QUrl &url)
+{
+    const auto &it = appIdCache.constFind(url);
+
+    if (it != appIdCache.constEnd()) {
+        return *it;
+    }
+
+    const KService::Ptr service = appData(url).service;
+    QString id = service->desktopEntryName();
+
+    // A renamed copy of a .desktop file outside the application dirs (e.g. on the desktop): use the
+    // installed application with the same Exec, which is what its windows are mapped to.
+    if (service->menuId().isEmpty() && !service->exec().isEmpty() && url.isLocalFile() && !KService::serviceByDesktopName(id)) {
+        const KService::List services = KApplicationTrader::query([&service](const KService::Ptr &installed) {
+            return installed->exec() == service->exec();
+        });
+
+        if (!services.isEmpty()) {
+            id = services.first()->desktopEntryName();
+        }
+    }
+
+    appIdCache.insert(url, id);
+
+    return id;
+}
+
 bool LauncherTasksModel::Private::requestAddLauncherToActivities(const QUrl &_url, const QStringList &_activities)
 {
     QUrl url(_url);
@@ -276,6 +308,7 @@ bool LauncherTasksModel::Private::requestRemoveLauncherFromActivities(const QUrl
             if (remove) {
                 q->beginRemoveRows(QModelIndex(), row, row);
                 appDataCache.remove(launcher);
+                appIdCache.remove(launcher);
                 launchersOrder.removeAt(row);
                 activitiesForLauncher.remove(url);
                 q->endRemoveRows();
@@ -318,7 +351,7 @@ QVariant LauncherTasksModel::data(const QModelIndex &index, int role) const
     } else if (role == Qt::DecorationRole) {
         return data.icon;
     } else if (role == AppId) {
-        return data.service->desktopEntryName();
+        return d->appId(url);
     } else if (role == AppName) {
         return data.service->name();
     } else if (role == GenericName) {
